WITH enriched AS (SELECT *, LAG(discount_pct, 2) OVER (PARTITION BY DATE_TRUNC('MONTH', starts_on), channel ORDER BY starts_on, id) AS prev_discount_pct, ROUND(discount_pct / SUM(discount_pct) OVER (PARTITION BY MONTH(ends_on), channel), 4) AS discount_pct_share, AVG(discount_pct) OVER (PARTITION BY channel ORDER BY starts_on, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS discount_pct_avg_6_prior, ROW_NUMBER() OVER (PARTITION BY promo_code ORDER BY ends_on DESC, id) AS row_seq, ROW_NUMBER() OVER (PARTITION BY channel, promo_code ORDER BY ends_on DESC, id) AS event_seq FROM promotions WHERE promo_code NOT IN ('WELCOME5', 'SPRING10', 'VIP')), scored AS (SELECT *, MAX(row_seq) OVER (PARTITION BY channel, promo_code ORDER BY discount_pct_avg_6_prior, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_max_row_seq, SUM(row_seq) OVER (PARTITION BY channel, promo_code ORDER BY discount_pct_avg_6_prior, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sum_row_seq, AVG(row_seq) OVER (PARTITION BY channel, promo_code ORDER BY discount_pct_avg_6_prior, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_avg_row_seq FROM enriched), scored_promotions AS (SELECT *, ROUND(prev_discount_pct / SUM(prev_discount_pct) OVER (PARTITION BY promo_code), 4) AS prev_discount_pct_share, RANK() OVER (PARTITION BY MONTH(ends_on), channel ORDER BY prev_discount_pct NULLS FIRST) AS prev_discount_pct_rank FROM scored), latest AS (SELECT *, RANK() OVER (PARTITION BY promo_code ORDER BY running_sum_row_seq DESC NULLS LAST) AS rank_in_group FROM scored_promotions QUALIFY rank_in_group = 1), attributed AS (SELECT a.*, pr.id AS promo_id, pr.promo_code AS promotion_promo_code, pr.discount_pct AS promotion_discount_pct FROM latest a LEFT JOIN promotions pr ON a.channel = pr.channel AND a.ends_on >= pr.starts_on AND a.ends_on < pr.ends_on + INTERVAL '14' DAY), ranked AS (SELECT id, promo_code, starts_on, discount_pct, discount_pct_avg_6_prior, event_seq, running_sum_row_seq, running_avg_row_seq, prev_discount_pct_share, prev_discount_pct_rank, rank_in_group, promo_id, promotion_promo_code, promotion_discount_pct FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY channel ORDER BY promo_id NULLS FIRST, id, promo_id) AS rn FROM attributed) ranked WHERE rn = 1), cleaned AS (SELECT id, discount_pct, discount_pct_avg_6_prior, running_sum_row_seq, running_avg_row_seq, prev_discount_pct_share, rank_in_group, promo_id, promotion_promo_code, CEIL(promotion_discount_pct) AS promotion_discount_pct_whole FROM ranked WHERE starts_on > TO_DATE('2023-04-05') AND starts_on > '2024-03-01') SELECT promo_id, CASE WHEN promotion_discount_pct_whole >= 74 THEN 'PREMIUM' ELSE 'STANDARD' END AS promotion_discount_pct_whole_tier, PERCENTILE_APPROX(promo_id, 0.95) AS promo_id_p95, COUNT(DISTINCT promotion_promo_code) AS distinct_promotion_promo_codes, APPROX_PERCENTILE(discount_pct_avg_6_prior, 0.95) AS discount_pct_avg_6_prior_p95 FROM cleaned GROUP BY promo_id, promotion_discount_pct_whole_tier
